/// Representation of an HTTP API error conforming to the RFC 7807
/// "Problem Details for HTTP APIs" specification.
class ProblemDetails implements Exception {
  const ProblemDetails({
    this.type = 'about:blank',
    required this.title,
    this.status,
    this.detail,
    this.instance,
    this.extensions = const <String, dynamic>{},
  });

  /// A URI reference that identifies the problem type.
  final String type;

  /// A short, human-readable summary of the problem type.
  final String title;

  /// The HTTP status code generated by the origin server for this occurrence.
  final int? status;

  /// A human-readable explanation specific to this occurrence of the problem.
  final String? detail;

  /// A URI reference that identifies the specific occurrence of the problem.
  final String? instance;

  /// Additional RFC 7807 extension members (e.g. validation `errors` map).
  final Map<String, dynamic> extensions;

  static const Set<String> _standardKeys = <String>{
    'type',
    'title',
    'status',
    'detail',
    'instance',
  };

  /// Deserializes a JSON map into a [ProblemDetails] instance.
  factory ProblemDetails.fromJson(
    Map<String, dynamic> json, {
    int? fallbackStatus,
    String? fallbackInstance,
  }) {
    final extra = <String, dynamic>{};
    for (final entry in json.entries) {
      if (!_standardKeys.contains(entry.key)) {
        extra[entry.key] = entry.value;
      }
    }

    final rawStatus = json['status'];
    final parsedStatus = switch (rawStatus) {
      final int value => value,
      final String value => int.tryParse(value) ?? fallbackStatus,
      _ => fallbackStatus,
    };

    return ProblemDetails(
      type: (json['type'] as String?)?.trim().isNotEmpty == true
          ? json['type'] as String
          : 'about:blank',
      title: (json['title'] as String?)?.trim().isNotEmpty == true
          ? json['title'] as String
          : (json['message'] as String?) ?? 'An unexpected error occurred.',
      status: parsedStatus,
      detail: json['detail'] as String?,
      instance: (json['instance'] as String?) ?? fallbackInstance,
      extensions: Map<String, dynamic>.unmodifiable(extra),
    );
  }

  /// Converts this [ProblemDetails] instance back to a JSON map.
  Map<String, dynamic> toJson() {
    return <String, dynamic>{
      'type': type,
      'title': title,
      if (status != null) 'status': status,
      if (detail != null) 'detail': detail,
      if (instance != null) 'instance': instance,
      ...extensions,
    };
  }

  /// User-facing message prioritizing [detail] over [title].
  String get userMessage =>
      (detail != null && detail!.trim().isNotEmpty) ? detail! : title;

  @override
  String toString() =>
      'ProblemDetails(status: $status, title: $title, detail: $detail, type: $type, instance: $instance)';
}
